int getResult(int n, int m, int* p)
{
	// 每个单位时间最少增加盒饭数量
	int min = 0;
	// 每个单位时间最多增加盒饭数量
	int max = arr_max(p, n);

	// 记录题解
	int ans = 0;

	// 二分
	while(min <= max) {
		int mid = (min + max) >> 1;

		// 检查每个单位时间增加mid份盒饭，是否可以满足0等待
		if(check(m, mid, p, n)) {
			// 可以满足的话，则mid就是一个可能解
			ans = mid;
			// 继续查找更优解
			max = mid - 1;
		} else {
			// 不满足的话，则说明mid取小了，下一轮应该取更大的mid
			min = mid + 1;
		}
	}

	return ans;
}

int check(int m, int add, int* p, int p_size) {
	 // P1 ≤ M ≤ 1000，因此这里 m - p[0] 必然大于等于 0
	m -= p[0];

	for(int i=1; i<p_size; i++) {
		m += add;

		if(m >= p[i]) {
			m -= p[i];
		} else {
			return 0;
		}
	}

	return 1;
}

int arr_max(int* arr, int arr_size)
{
	int ans = arr[0];

	for(int i=1; i<arr_size; i++) {
		ans = MAX(ans, arr[i]);
	}

	return ans;
}
